internal sealed class SubstitutionConfiguration : IEntityTypeConfiguration<Substitution>
{
    public void Configure(EntityTypeBuilder<Substitution> builder)
    {
        builder.ToTable("substitutions");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.SlotId).HasColumnName("slot_id");
        builder.Property(e => e.Date).HasColumnName("date").HasColumnType("date");
        builder.Property(e => e.SubstituteId).HasColumnName("substitute_id");
        builder.Property(e => e.Reason).HasColumnName("reason").HasColumnType("nvarchar(160)").HasMaxLength(160);
        builder.Property(e => e.CreatedByName).HasColumnName("created_by_name").HasColumnType("nvarchar(100)").HasMaxLength(100);
        builder.HasIndex(e => new { e.SlotId, e.Date }).IsUnique().HasDatabaseName("uq_substitution");
        builder.HasOne(e => e.TimetableSlot).WithMany(p => p.Substitutions).HasForeignKey(e => e.SlotId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Substitute).WithMany(p => p.Substitutions).HasForeignKey(e => e.SubstituteId).OnDelete(DeleteBehavior.NoAction);
    }
}
